CREATE VIEW public.finance_transactions WITH (security_invoker = true) AS SELECT t.id,t.deal_id,d.ref AS deal_ref,d.buyer_id,d.seller_id,t.kind,t.amount::text AS amount,t.fee::text AS fee,t.currency,t.status,t.provider,t.provider_ref,t.created_at,t.updated_at,t.original_transaction_id,t.milestone_id,t.payout_split_id,t.fx_quote_id, CASE WHEN t.status='succeeded' AND t.kind='funding' THEN 'captured_simulated' WHEN t.status='succeeded' AND t.kind='refund' THEN 'refund_confirmed_simulated' WHEN t.status='succeeded' AND t.kind='release' THEN 'payout_confirmed_simulated' ELSE t.status END AS operational_status, 'sandbox'::text AS environment FROM public.deal_transactions t JOIN public.deals d ON d.id=t.deal_id;
GRANT SELECT ON public.finance_transactions TO authenticated,service_role;
CREATE TABLE public.finance_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('provider_proposal','routing_proposal','approval','reconciliation_import','reconciliation_resolution','routing_simulation','export')), subject_id text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, reason text NOT NULL, idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(actor_id,idempotency_key));
GRANT SELECT ON public.finance_records TO authenticated;
GRANT SELECT,INSERT ON public.finance_records TO service_role;
ALTER TABLE public.finance_records ENABLE ROW LEVEL SECURITY;
CREATE POLICY finance_staff_read ON public.finance_records FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'staff'));
CREATE INDEX finance_records_subject ON public.finance_records(subject_id,created_at);
CREATE UNIQUE INDEX finance_one_approval ON public.finance_records(subject_id) WHERE kind='approval';
CREATE FUNCTION public.finance_append_record(_actor uuid,_kind text,_subject text,_payload jsonb,_reason text,_key uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; proposed public.finance_records; oldrecord public.finance_records; admin_role boolean; narrowed boolean; BEGIN
admin_role := public.has_role(_actor,'admin') OR public.has_role(_actor,'super_admin');
IF NOT(admin_role OR public.has_role(_actor,'staff')) THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF NOT admin_role AND (public.has_role(_actor,'compliance') OR (public.has_role(_actor,'support') AND NOT public.has_role(_actor,'finance'))) THEN RAISE EXCEPTION 'Finance capability required'; END IF;
IF _kind IN ('provider_proposal','routing_proposal','approval') AND NOT admin_role THEN RAISE EXCEPTION 'Admin capability required'; END IF;
IF length(trim(_reason))<3 OR length(_reason)>2000 THEN RAISE EXCEPTION 'Reason required'; END IF;
IF octet_length(_payload::text)>500000 THEN RAISE EXCEPTION 'Record too large'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(_actor::text||_key::text));
SELECT * INTO oldrecord FROM public.finance_records WHERE actor_id=_actor AND idempotency_key=_key;
IF FOUND THEN IF oldrecord.kind<>_kind OR oldrecord.subject_id<>_subject OR oldrecord.payload<>_payload OR oldrecord.reason<>_reason THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN oldrecord.id; END IF;
IF _kind='approval' THEN
 SELECT * INTO proposed FROM public.finance_records WHERE id::text=_subject FOR UPDATE;
 IF NOT FOUND OR proposed.kind NOT IN ('provider_proposal','routing_proposal') THEN RAISE EXCEPTION 'Proposal missing'; END IF;
 IF proposed.actor_id=_actor THEN RAISE EXCEPTION 'Independent approver required'; END IF;
END IF;
IF _kind IN ('provider_proposal','routing_proposal') AND (_payload->>'environment' IS DISTINCT FROM 'sandbox' OR coalesce((_payload->>'live')::boolean,false)) THEN RAISE EXCEPTION 'Live operations disabled'; END IF;
INSERT INTO public.finance_records(actor_id,kind,subject_id,payload,reason,idempotency_key) VALUES(_actor,_kind,_subject,_payload,_reason,_key) RETURNING id INTO result;
PERFORM public.staff_control_audit(_actor,'FINANCE_'||upper(_kind),'finance_records',result::text,NULL,_payload||jsonb_build_object('subject',_subject),_reason);
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.finance_append_record(uuid,text,text,jsonb,text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.finance_append_record(uuid,text,text,jsonb,text,uuid) TO service_role;